INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6401532, 949223, 43774, '<td valign="top">Lovely portrait in a great setting but a bit dark/underexposed.</td>', 'Lovely portrait in a great setting but a bit dark/underexposed.', '2011-05-02 10:33:41.000000', NULL, 1),
(6401534, 949316, 15711, '<td valign="top">The missing petals and offset stem is a nice brake from the symmetry.  A touch severe with the orange border. :) 6</td>', 'The missing petals and offset stem is a nice brake from the symmetry.  A touch severe with the orange border. :) 6', '2011-05-02 10:33:58.000000', NULL, 1),
(6401535, 949149, 43774, '<td valign="top">1 pixel off a square crop, DNMC!!! Just kidding, wonderful closeup, great eyes.</td>', '1 pixel off a square crop, DNMC!!! Just kidding, wonderful closeup, great eyes.', '2011-05-02 10:34:29.000000', NULL, 1),
(6401536, 949363, 15711, '<td valign="top">I''m smiling.  Beautifully done narrow DOF.  I like how the bee is offset.  Gorgeous. Very dreamlike.  That bokeh is some kind of delicious!!</td>', 'I''m smiling.  Beautifully done narrow DOF.  I like how the bee is offset.  Gorgeous. Very dreamlike.  That bokeh is some kind of delicious!!', '2011-05-02 10:34:34.000000', NULL, 1),
(6401537, 948960, 43774, '<td valign="top">Clever composition, nice.</td>', 'Clever composition, nice.', '2011-05-02 10:34:42.000000', NULL, 1),
(6401538, 949288, 15711, '<td valign="top">I can see this as a contemporary art piece in an exhibit.  Nice.</td>', 'I can see this as a contemporary art piece in an exhibit.  Nice.', '2011-05-02 10:34:52.000000', NULL, 1),
(6401541, 949155, 15711, '<td valign="top">A bit heavy on the border.  I do love our rotunda though. I''ve been known to lie on my back amidst many tourist and DPC officers to shoot this exact image. :)</td>', 'A bit heavy on the border.  I do love our rotunda though. I''ve been known to lie on my back amidst many tourist and DPC officers to shoot this exact image. :)', '2011-05-02 10:35:31.000000', NULL, 1),
(6401542, 948531, 15711, '<td valign="top">I like it.  Great contrasts.</td>', 'I like it.  Great contrasts.', '2011-05-02 10:35:42.000000', NULL, 1),
(6401543, 949305, 15711, '<td valign="top">Well done.  Your edit serves it well. :)</td>', 'Well done.  Your edit serves it well. :)', '2011-05-02 10:35:55.000000', NULL, 1),
(6401544, 948959, 15711, '<td valign="top">Loving the sky.  The complimentary brown/blue color scheme really works.  I ike hos the mission is centered, but the flag and the falling pickets take away from the symmetry of it.  Nicely done.</td>', 'Loving the sky.  The complimentary brown/blue color scheme really works.  I ike hos the mission is centered, but the flag and the falling pickets take away from the symmetry of it.  Nicely done.', '2011-05-02 10:36:47.000000', NULL, 1),
(6401545, 949357, 15711, '<td valign="top">Wonderfully kind expression. I love the catch lights in his eyes.  For some reason, I wish he were centered in the shot.  Love the play of light and shadow. 7</td>', 'Wonderfully kind expression. I love the catch lights in his eyes.  For some reason, I wish he were centered in the shot.  Love the play of light and shadow. 7', '2011-05-02 10:37:33.000000', NULL, 1),
(6401550, 948718, 43774, '<td valign="top">Cripple? How rude and politically incorrect! My partner is in a wheelchair and never in a million years would I refer to him as a cripple. Sorry but your title struck a nerve with me.<br/> <br/>That being said I will rate your photo on its merits and not on its title. I would prefer if the white area around the painted sign were even. It''s an okay photo, nothing to stand out from the crowd.</td>', 'Cripple? How rude and politically incorrect! My partner is in a wheelchair and never in a million years would I refer to him as a cripple. Sorry but your title struck a nerve with me. That being said I will rate your photo on its merits and not on its title. I would prefer if the white area around the painted sign were even. It''s an okay photo, nothing to stand out from the crowd.', '2011-05-02 10:41:02.000000', NULL, 1),
(6401553, 949425, 43774, '<td valign="top">Really nice colours.</td>', 'Really nice colours.', '2011-05-02 10:41:49.000000', NULL, 1),
(6401556, 949047, 43774, '<td valign="top">Very cute.</td>', 'Very cute.', '2011-05-02 10:42:39.000000', NULL, 1),
