(6401894, 948565, 43774, '<td valign="top">It looks a little tilted to me, would love to see it lined up better.</td>', 'It looks a little tilted to me, would love to see it lined up better.', '2011-05-02 14:01:58.000000', NULL, 1),
(6401896, 948468, 113156, '<td valign="top">I feel like i know this place, lovely textures and very good B&amp;W.</td>', 'I feel like i know this place, lovely textures and very good B&W.', '2011-05-02 14:02:37.000000', NULL, 1),
(6401899, 948144, 47488, '<td valign="top">Great use of the square crop and nice colors!</td>', 'Great use of the square crop and nice colors!', '2011-05-02 14:05:39.000000', NULL, 1),
(6401903, 948976, 114225, '<td valign="top">Black and white was the perfect choice for this scene. As is the composition. Without the normal rule of thirds, angles become more important to me, and the competing angles of the sidewalk and the person work well towether.</td>', 'Black and white was the perfect choice for this scene. As is the composition. Without the normal rule of thirds, angles become more important to me, and the competing angles of the sidewalk and the person work well towether.', '2011-05-02 14:06:47.000000', NULL, 1),
(6401905, 949413, 114225, '<td valign="top">Interesting choice of composition. For a square crop, I kind of feel that a more balanced composition would have worked a bit better. Still, a nice photo.</td>', 'Interesting choice of composition. For a square crop, I kind of feel that a more balanced composition would have worked a bit better. Still, a nice photo.', '2011-05-02 14:07:47.000000', NULL, 1),
(6401906, 949194, 47488, '<td valign="top">This works so well in black and white!  Great quirky image.</td>', 'This works so well in black and white!  Great quirky image.', '2011-05-02 14:08:24.000000', NULL, 1),
(6401907, 949218, 114225, '<td valign="top">Great use of right angles for your subject. The square crop really favors a perfectly right angle.</td>', 'Great use of right angles for your subject. The square crop really favors a perfectly right angle.', '2011-05-02 14:08:41.000000', NULL, 1),
(6401910, 949160, 114225, '<td valign="top">Great emotion conveyed in this image. I''m struggling with the haziness of the photo. On the one hand, it seems to add to the atmosphere. On the other hand, it''s making me squint to try to see the photo better.</td>', 'Great emotion conveyed in this image. I''m struggling with the haziness of the photo. On the one hand, it seems to add to the atmosphere. On the other hand, it''s making me squint to try to see the photo better.', '2011-05-02 14:09:51.000000', NULL, 1),
(6401912, 948553, 114225, '<td valign="top">Good use of angles and lines in a framing that favors that type of thing.</td>', 'Good use of angles and lines in a framing that favors that type of thing.', '2011-05-02 14:10:36.000000', NULL, 1),
(6401914, 948991, 114225, '<td valign="top">Nice idea to have an explosion of flower from top down. But the lack of tack sharp focus and the bit of green leaf in the background are hurting this photo in my mind.</td>', 'Nice idea to have an explosion of flower from top down. But the lack of tack sharp focus and the bit of green leaf in the background are hurting this photo in my mind.', '2011-05-02 14:11:40.000000', NULL, 1),
(6401916, 949322, 114225, '<td valign="top">Nicely done. I appreciate how the angle of movement of the cows is perpendicular to the main tree, that really adds to the composition.</td>', 'Nicely done. I appreciate how the angle of movement of the cows is perpendicular to the main tree, that really adds to the composition.', '2011-05-02 14:12:21.000000', NULL, 1),
(6401934, 948048, 75585, '<td valign="top">Not voting; however, for me this does not meet the challenge since it is not square.</td>', 'Not voting; however, for me this does not meet the challenge since it is not square.', '2011-05-02 14:24:57.000000', NULL, 1),
(6401935, 949401, 75585, '<td valign="top">Not voting; however, this photo really works in a square composition.</td>', 'Not voting; however, this photo really works in a square composition.', '2011-05-02 14:25:31.000000', NULL, 1),
(6401936, 949248, 75585, '<td valign="top">Not voting - however, this is a very cute shot!</td>', 'Not voting - however, this is a very cute shot!', '2011-05-02 14:26:13.000000', NULL, 1),
(6401937, 948742, 75585, '<td valign="top">Not voting; however, this does not meet the challenge as it is not a square.  I really really like your color pallete in this - very soothing.</td>', 'Not voting; however, this does not meet the challenge as it is not a square.  I really really like your color pallete in this - very soothing.', '2011-05-02 14:27:13.000000', NULL, 1),
(6401940, 948923, 129607, '<td valign="top">Beautiful photo and idea. I think the picture would be better if the lighting was a bit brighter.</td>', 'Beautiful photo and idea. I think the picture would be better if the lighting was a bit brighter.', '2011-05-02 14:30:13.000000', NULL, 1),
(6401941, 949411, 75585, '<td valign="top">Not voting; however, I really wish this was a square crop.</td>', 'Not voting; however, I really wish this was a square crop.', '2011-05-02 14:30:17.000000', NULL, 1),
(6401942, 948391, 129607, '<td valign="top">Great idea... beautiful outcome! Terrific!</td>', 'Great idea... beautiful outcome! Terrific!', '2011-05-02 14:30:38.000000', NULL, 1),
(6401943, 948579, 75585, '<td valign="top">Not voting - I think you really could have done a true square crop on this and it would still be gorgeous.</td>', 'Not voting - I think you really could have done a true square crop on this and it would still be gorgeous.', '2011-05-02 14:31:22.000000', NULL, 1),
(6401944, 949303, 75585, '<td valign="top">Not voting; however, I really think this still would have worked in a square crop.  Gorgeous!!</td>', 'Not voting; however, I really think this still would have worked in a square crop.  Gorgeous!!', '2011-05-02 14:32:22.000000', NULL, 1),
(6401961, 948665, 131399, '<td valign="top">Have to give high marks for content</td>', 'Have to give high marks for content', '2011-05-02 14:51:28.000000', NULL, 1),
(6401966, 949296, 108069, '<td valign="top">Stunning shot with processing that is well out of my league. I don''t see how the square crop was necessary or beneficial to this but I''m not voting so it doesn''t matter. I''d wager it''ll do extremely well.</td>', 'Stunning shot with processing that is well out of my league. I don''t see how the square crop was necessary or beneficial to this but I''m not voting so it doesn''t matter. I''d wager it''ll do extremely well.', '2011-05-02 14:53:05.000000', NULL, 1),
(6401969, 949413, 108069, '<td valign="top">Great image. Nice and sharp with excellent colors. Composition works perfectly for the square crop.</td>', 'Great image. Nice and sharp with excellent colors. Composition works perfectly for the square crop.', '2011-05-02 14:53:46.000000', NULL, 1),
(6401979, 949315, 108069, '<td valign="top">Excellent photo. Wonderful contrast, purplish hues vs. the stark white. Square crop really lends itself to the presentation, giving a nice perspective and sense of size. Nice one.</td>', 'Excellent photo. Wonderful contrast, purplish hues vs. the stark white. Square crop really lends itself to the presentation, giving a nice perspective and sense of size. Nice one.', '2011-05-02 15:18:16.000000', NULL, 1),
(6401986, 949092, 108069, '<td valign="top">Quite an interesting photo. The square crop adds depth to this, as instead of your eye taking in the landscape your eye is immediately drawn straight forward into the photo. Great perspective. Nice one.</td>', 'Quite an interesting photo. The square crop adds depth to this, as instead of your eye taking in the landscape your eye is immediately drawn straight forward into the photo. Great perspective. Nice one.', '2011-05-02 15:35:29.000000', NULL, 1),
(6401991, 949160, 108069, '<td valign="top">Big story here. Excellent use of the square crop with center composition, especially with them huddled together. Powerful shot. On top of that I love the processing. I have tried a similar approach recently and have failed miserably, so I hope I can pick up a few tips afterwards. Great stuff.</td>', 'Big story here. Excellent use of the square crop with center composition, especially with them huddled together. Powerful shot. On top of that I love the processing. I have tried a similar approach recently and have failed miserably, so I hope I can pick up a few tips afterwards. Great stuff.', '2011-05-02 15:45:55.000000', NULL, 1),
(6401994, 949155, 108069, '<td valign="top">This is essentially what I think of when I think of the perfect subject for a square crop: Symmetry. I took a similar shot that I would have loved to have entered but I took it the day before the challenge was announced and I had no chance of getting back to it. Nice graduated tones, well framed. Great find.</td>', 'This is essentially what I think of when I think of the perfect subject for a square crop: Symmetry. I took a similar shot that I would have loved to have entered but I took it the day before the challenge was announced and I had no chance of getting back to it. Nice graduated tones, well framed. Great find.', '2011-05-02 15:53:02.000000', NULL, 1),
(6401998, 948468, 119188, '<td valign="top">awesome shot. Reminds me of the "Exorcist" stairs in Georgetown or just from the movie ;)</td>', 'awesome shot. Reminds me of the "Exorcist" stairs in Georgetown or just from the movie ;)', '2011-05-02 16:01:39.000000', NULL, 1),
(6402001, 949435, 119188, '<td valign="top">Another good title would have been "Don''t worry, be happy" I like it.</td>', 'Another good title would have been "Don''t worry, be happy" I like it.', '2011-05-02 16:05:50.000000', NULL, 1),
(6402003, 948549, 119188, '<td valign="top">HA! Must be camera shy looking away like that.</td>', 'HA! Must be camera shy looking away like that.', '2011-05-02 16:07:26.000000', NULL, 1),
(6402007, 949296, 119188, '<td valign="top">wow! cool shot.</td>', 'wow! cool shot.', '2011-05-02 16:09:17.000000', NULL, 1),
(6402008, 949194, 119188, '<td valign="top">nice pun and photo</td>', 'nice pun and photo', '2011-05-02 16:10:18.000000', NULL, 1),
(6402009, 948830, 119188, '<td valign="top">A lot of people are not into the HDR thing but I really like it. Sometimes it brings out detail you would not normally notice. Great shot and nice processing.</td>', 'A lot of people are not into the HDR thing but I really like it. Sometimes it brings out detail you would not normally notice. Great shot and nice processing.', '2011-05-02 16:12:49.000000', NULL, 1),
(6402012, 949398, 46885, '<td valign="top">This is technically very, very good. But this is one instance where I wouldn''t want to see square and would like to have some looking space (preferably positive, but negative might add some value too). But - well done on everything else. Looking forward for detailed description as to how this was achieved.</td>', 'This is technically very, very good. But this is one instance where I wouldn''t want to see square and would like to have some looking space (preferably positive, but negative might add some value too). But - well done on everything else. Looking forward for detailed description as to how this was achieved.', '2011-05-02 16:15:58.000000', NULL, 1),
(6402015, 949288, 46885, '<td valign="top">Easily a winner, though it would be brilliant even at standard 3:4. How do you convert colour into such terrific mono?</td>', 'Easily a winner, though it would be brilliant even at standard 3:4. How do you convert colour into such terrific mono?', '2011-05-02 16:16:44.000000', NULL, 1),
(6402016, 948718, 46885, '<td valign="top">Sometimes simplicity is too simple...</td>', 'Sometimes simplicity is too simple...', '2011-05-02 16:17:06.000000', NULL, 1),
(6402017, 949409, 46885, '<td valign="top">Is it? Can''t tell. I think Japanese competitor hit you thus screwing focusing.</td>', 'Is it? Can''t tell. I think Japanese competitor hit you thus screwing focusing.', '2011-05-02 16:17:47.000000', NULL, 1),
(6402019, 949305, 46885, '<td valign="top">Very correct, very clean, very boring.</td>', 'Very correct, very clean, very boring.', '2011-05-02 16:18:34.000000', NULL, 1),
(6402020, 949328, 46885, '<td valign="top">I''d tighten it a lot. You don''t need a lot of debris to illustrate the point.</td>', 'I''d tighten it a lot. You don''t need a lot of debris to illustrate the point.', '2011-05-02 16:19:11.000000', NULL, 1),
(6402022, 949168, 119188, '<td valign="top">It is hard to vote on something when you do not understand it. It took a bit of research to know what you were going for. Sorry, just not much of a reader ;) I had a hard time on this one.</td>', 'It is hard to vote on something when you do not understand it. It took a bit of research to know what you were going for. Sorry, just not much of a reader ;) I had a hard time on this one.', '2011-05-02 16:19:51.000000', NULL, 1),
(6402024, 949401, 46885, '<td valign="top">Try monochrome. Some artefacts cropping up on the inner sides of fingers.. Good idea, thou.</td>', 'Try monochrome. Some artefacts cropping up on the inner sides of fingers.. Good idea, thou.', '2011-05-02 16:20:32.000000', NULL, 1),
(6402025, 949384, 46885, '<td valign="top">Well done, but I am not convinced putting that much into upper third is not unbalancing this. Also needs some contrast tweaks on upper white squares which show unwanted detail.</td>', 'Well done, but I am not convinced putting that much into upper third is not unbalancing this. Also needs some contrast tweaks on upper white squares which show unwanted detail.', '2011-05-02 16:21:46.000000', NULL, 1),
(6402026, 949438, 46885, '<td valign="top">Someone with ''American car'' shot had the same misfortune, but at least his camera survived. Did it hurt?</td>', 'Someone with ''American car'' shot had the same misfortune, but at least his camera survived. Did it hurt?', '2011-05-02 16:23:23.000000', NULL, 1),
(6402028, 949426, 119188, '<td valign="top">The red border really draws my attention. It makes it hard to center my focus on the composition of the photo. The photo itself is good.</td>', 'The red border really draws my attention. It makes it hard to center my focus on the composition of the photo. The photo itself is good.', '2011-05-02 16:23:46.000000', NULL, 1),
(6402031, 949160, 46885, '<td valign="top">For a faded 70s look the cans are a bit too modern. Unless designed to look sloppy, proper white/black point would fix the range. I''d also tighten it about 100 pix each side.</td>', 'For a faded 70s look the cans are a bit too modern. Unless designed to look sloppy, proper white/black point would fix the range. I''d also tighten it about 100 pix each side.', '2011-05-02 16:25:19.000000', NULL, 1),
(6402032, 948391, 46885, '<td valign="top">Obvious, but good! Does that normally get framed and put on the wall? If so, I''d put a little sticker saying ''In a curry emergency, break the glass''.</td>', 'Obvious, but good! Does that normally get framed and put on the wall? If so, I''d put a little sticker saying ''In a curry emergency, break the glass''.', '2011-05-02 16:26:32.000000', NULL, 1),
(6402033, 948097, 46885, '<td valign="top">All but perfect, but I''d want a hint of glasses actually having glass in them.</td>', 'All but perfect, but I''d want a hint of glasses actually having glass in them.', '2011-05-02 16:27:11.000000', NULL, 1),
(6402034, 948828, 46885, '<td valign="top">Something in me wants to see the green dude symmetrical into the square, but then, of course, we''d lose the flower. Could you reframe?</td>', 'Something in me wants to see the green dude symmetrical into the square, but then, of course, we''d lose the flower. Could you reframe?', '2011-05-02 16:28:45.000000', NULL, 1),
(6402037, 949312, 46885, '<td valign="top">This is not benefiting from tight square of the frame. I''d want some space on the back of the car and the bull, otherwise there''s too much of boring, unfocussed grass in the shot.</td>', 'This is not benefiting from tight square of the frame. I''d want some space on the back of the car and the bull, otherwise there''s too much of boring, unfocussed grass in the shot.', '2011-05-02 16:30:19.000000', NULL, 1),
(6402038, 948542, 119188, '<td valign="top">I get it, people like birds. Colorful and interesting but overdone for me. I really like this one though because it has a story to it. Its not just another bird on a tree branch. This photo has a sharp subject, great texture and good bokeh. Well done.</td>', 'I get it, people like birds. Colorful and interesting but overdone for me. I really like this one though because it has a story to it. Its not just another bird on a tree branch. This photo has a sharp subject, great texture and good bokeh. Well done.', '2011-05-02 16:30:40.000000', NULL, 1),
(6402040, 948515, 46885, '<td valign="top">No, there''s also plenty of boring debris on the foreground which completely steal the attention. Why not turn the whole frame into a silhouette?</td>', 'No, there''s also plenty of boring debris on the foreground which completely steal the attention. Why not turn the whole frame into a silhouette?', '2011-05-02 16:31:38.000000', NULL, 1),
(6402041, 948121, 46885, '<td valign="top">Good atmosphere, but I''d actually wanted to expand it a little to see the setting. Also needs a bit more focus on the front flower. But good pic otherwise.</td>', 'Good atmosphere, but I''d actually wanted to expand it a little to see the setting. Also needs a bit more focus on the front flower. But good pic otherwise.', '2011-05-02 16:32:46.000000', NULL, 1),
(6402042, 949373, 46885, '<td valign="top">Too much dead space around the spider for me.</td>', 'Too much dead space around the spider for me.', '2011-05-02 16:33:24.000000', NULL, 1),
(6402044, 949441, 46885, '<td valign="top">Looks utterly unnatural.</td>', 'Looks utterly unnatural.', '2011-05-02 16:33:58.000000', NULL, 1),
(6402047, 948048, 46885, '<td valign="top">Is he looking spelling of ''square''? Good shot, but kindda misses the theme.</td>', 'Is he looking spelling of ''square''? Good shot, but kindda misses the theme.', '2011-05-02 16:34:39.000000', NULL, 1),
(6402049, 949168, 54645, '<td valign="top">What a wonderfully mysterious image. 10</td>', 'What a wonderfully mysterious image. 10', '2011-05-02 16:35:28.000000', NULL, 1),
(6402050, 949398, 119188, '<td valign="top">awesome photo. Well done. I need to learn this technique.</td>', 'awesome photo. Well done. I need to learn this technique.', '2011-05-02 16:36:09.000000', NULL, 1),
(6402051, 949195, 46885, '<td valign="top">I''d do something with the central hole, the mundane-ness wrecks the whole ManRayish point of everything else.</td>', 'I''d do something with the central hole, the mundane-ness wrecks the whole ManRayish point of everything else.', '2011-05-02 16:37:09.000000', NULL, 1),
(6402052, 948742, 46885, '<td valign="top">Lovely colour, but wrong kind of square.</td>', 'Lovely colour, but wrong kind of square.', '2011-05-02 16:38:44.000000', NULL, 1),
(6402056, 948830, 46885, '<td valign="top">overcooked no end.</td>', 'overcooked no end.', '2011-05-02 16:39:44.000000', NULL, 1),
(6402057, 949256, 119188, '<td valign="top">FORWARD HARCH! sorry couldn''t help it... I am brain washed for life. Nice symmetry.</td>', 'FORWARD HARCH! sorry couldn''t help it... I am brain washed for life. Nice symmetry.', '2011-05-02 16:40:39.000000', NULL, 1),
(6402060, 949440, 46885, '<td valign="top">Someone did it recently with tulips, but with a more careful lighting. It''s hard to get the green in a prefect circle, but square framing draws attention to this. As such the flower is drawn to the bottom a bit.</td>', 'Someone did it recently with tulips, but with a more careful lighting. It''s hard to get the green in a prefect circle, but square framing draws attention to this. As such the flower is drawn to the bottom a bit.', '2011-05-02 16:42:43.000000', NULL, 1),
(6402061, 948665, 119188, '<td valign="top">haha nice. That was the first thing that came to mind before even reading the title. Great shot.</td>', 'haha nice. That was the first thing that came to mind before even reading the title. Great shot.', '2011-05-02 16:43:36.000000', NULL, 1),
(6402062, 949248, 46885, '<td valign="top">Gosh, mannequins come seriously human-like these days. Looks seriously overcooked to me.</td>', 'Gosh, mannequins come seriously human-like these days. Looks seriously overcooked to me.', '2011-05-02 16:44:05.000000', NULL, 1),
(6402063, 949412, 46885, '<td valign="top">... which says ''just because I am an albino why do people get it wrong with exposure time after time''?</td>', '... which says ''just because I am an albino why do people get it wrong with exposure time after time''?', '2011-05-02 16:44:49.000000', NULL, 1),
(6402065, 948997, 46885, '<td valign="top">The artsy treatment certainly takes away from the realism of the shot. Would work well on a still life, doesn''t really do it much for a ''street'' shot.</td>', 'The artsy treatment certainly takes away from the realism of the shot. Would work well on a still life, doesn''t really do it much for a ''street'' shot.', '2011-05-02 16:46:16.000000', NULL, 1),
(6402066, 948819, 46885, '<td valign="top">Square framing really wants the spokes to be of the same length. Looks unbalanced to me.</td>', 'Square framing really wants the spokes to be of the same length. Looks unbalanced to me.', '2011-05-02 16:47:06.000000', NULL, 1),
(6402067, 949422, 119188, '<td valign="top">This is so awesome. How did you even notice this? This is BA (bad ass). Great job.</td>', 'This is so awesome. How did you even notice this? This is BA (bad ass). Great job.', '2011-05-02 16:47:20.000000', NULL, 1),
(6402068, 949329, 46885, '<td valign="top">Were you aiming for the bokeh challenge?</td>', 'Were you aiming for the bokeh challenge?', '2011-05-02 16:47:56.000000', NULL, 1),
(6402074, 948541, 46885, '<td valign="top">Lovely detail and colur. I''d tighten it a bit, perhaps placing the surver slightly down off-center.</td>', 'Lovely detail and colur. I''d tighten it a bit, perhaps placing the surver slightly down off-center.', '2011-05-02 16:51:33.000000', NULL, 1),
(6402076, 949218, 119188, '<td valign="top">whoa that looks painful. What great ability she has. Nicely shot with great textures and tones. I am typing more now at this point because I cannot stop looking at it.</td>', 'whoa that looks painful. What great ability she has. Nicely shot with great textures and tones. I am typing more now at this point because I cannot stop looking at it.', '2011-05-02 16:52:22.000000', NULL, 1);
