(6402092, 948850, 119188, '<td valign="top">for some reason I imagine them on little cell phones. Nice capture</td>', 'for some reason I imagine them on little cell phones. Nice capture', '2011-05-02 17:04:23.000000', NULL, 1),
(6402093, 948136, 119188, '<td valign="top">vibrant!</td>', 'vibrant!', '2011-05-02 17:04:46.000000', NULL, 1),
(6402094, 948578, 119188, '<td valign="top">&amp; SHARP! Well done</td>', '& SHARP! Well done', '2011-05-02 17:05:31.000000', NULL, 1),
(6402095, 949010, 108069, '<td valign="top">Nice abstract. Like a dreamsicle. Pulsating, graduated colors and tones. Nice stuff.</td>', 'Nice abstract. Like a dreamsicle. Pulsating, graduated colors and tones. Nice stuff.', '2011-05-02 17:06:33.000000', NULL, 1),
(6402096, 948541, 119188, '<td valign="top">I really don''t know what to say that isn''t obvious. Wicked shot.</td>', 'I really don''t know what to say that isn''t obvious. Wicked shot.', '2011-05-02 17:07:26.000000', NULL, 1),
