INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6407427, 949409, 11769, '<td valign="top">I loved those big old boats, those dinosaurs, when you opened the hood you could see the ground under the engine. 10 MPG but gas went for 24 cents a gallon premium, cruse around all day on change.<br/>Maybe it was just a dream I had.</td>', 'I loved those big old boats, those dinosaurs, when you opened the hood you could see the ground under the engine. 10 MPG but gas went for 24 cents a gallon premium, cruse around all day on change.Maybe it was just a dream I had.', '2011-05-08 10:37:31.000000', NULL, 1),
(6407431, 949438, 11769, '<td valign="top">I see things that almost materialize then are lost. Profound things I am unable to fathom, they are just out of reach. Maybe if I look long enough I might understand but I realize I''m trapped in this place and trapped by my unwillingness to take the step it would take to see.</td>', 'I see things that almost materialize then are lost. Profound things I am unable to fathom, they are just out of reach. Maybe if I look long enough I might understand but I realize I''m trapped in this place and trapped by my unwillingness to take the step it would take to see.', '2011-05-08 10:59:49.000000', NULL, 1),
